cat > /tmp/ref/tests/dump.test.ts <<'EOF'
import { describe, it } from 'vitest';
import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { GBNF } from '../src/index.js';

describe('dump', () => {
  it('dumps', () => {
    const cases = JSON.parse(readFileSync('/tmp/cases.json', 'utf8'));
    const grammarDir = join(import.meta.dirname, 'iteration', 'grammars');
    const grammars = [...cases.grammars];
    for (const f of readdirSync(grammarDir).sort()) {
      if (f.endsWith('.gbnf')) grammars.push(readFileSync(join(grammarDir, f), 'utf8'));
    }
    const inputs: string[] = cases.inputs;
    const out: Record<string, string> = {};
    grammars.forEach((grammar: string, gi: number) => {
      inputs.forEach(input => {
        const key = `${gi}|${JSON.stringify(input)}`;
        let result: string;
        try {
          const state = GBNF(grammar, input);
          const rules = [...state].map(r => JSON.stringify(r)).sort();
          result = `OK ${state.size} ${JSON.stringify(rules)}`;
        } catch (err) {
          result = `ERR ${(err as Error).name}: ${(err as Error).message}`;
        }
        out[key] = result;
        // incremental adds
        let key2 = `${gi}|${JSON.stringify(input)}|inc`;
        try {
          let state = GBNF(grammar);
          for (const ch of Array.from(input)) state = state.add(ch);
          const rules = [...state].map(r => JSON.stringify(r)).sort();
          out[key2] = `OK ${state.size} ${JSON.stringify(rules)}`;
        } catch (err) {
          out[key2] = `ERR ${(err as Error).name}: ${(err as Error).message}`;
        }
      });
    });
    writeFileSync('/tmp/ref_out.json', JSON.stringify(out, null, 1));
  });
});
