import json, os, sys
sys.path.insert(0, '/workspace/ported_implementation')
from gbnf import GBNF, GrammarParseError, InputParseError

cases = json.load(open('/tmp/cases.json'))
gdir = '/workspace/reference_implementation/tests/iteration/grammars'
grammars = list(cases['grammars'])
for f in sorted(os.listdir(gdir)):
    if f.endswith('.gbnf'):
        grammars.append(open(os.path.join(gdir, f)).read())

def js(o):
    return json.dumps(o, separators=(',', ':'), ensure_ascii=False)

def rules_of(state):
    return sorted(js(r.__dict__) for r in state)

out = {}
for gi, grammar in enumerate(grammars):
    for inp in cases['inputs']:
        key = f"{gi}|{js(inp)}"
        try:
            state = GBNF(grammar, inp)
            out[key] = f"OK {state.size} {js(rules_of(state))}"
        except (GrammarParseError, InputParseError) as e:
            out[key] = f"ERR {e.name}: {e}"
        except Exception as e:
            out[key] = f"ERR {type(e).__name__}: {e}"
        key2 = key + "|inc"
        try:
            state = GBNF(grammar)
            for ch in inp:
                state = state.add(ch)
            out[key2] = f"OK {state.size} {js(rules_of(state))}"
        except (GrammarParseError, InputParseError) as e:
            out[key2] = f"ERR {e.name}: {e}"
        except Exception as e:
            out[key2] = f"ERR {type(e).__name__}: {e}"
json.dump(out, open('/tmp/py_out.json', 'w'), indent=1)
EOF
